import{_ as a,o as t,c as r,a3 as i}from"./chunks/framework.CZBGEXos.js";const u=JSON.parse('{"title":"Rol: Prevencionista","description":"","frontmatter":{},"headers":[],"relativePath":"roles/prevencionista.md","filePath":"roles/prevencionista.md"}'),s={name:"roles/prevencionista.md"};function o(n,e,d,l,c,m){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="rol-prevencionista" tabindex="-1">Rol: Prevencionista <a class="header-anchor" href="#rol-prevencionista" aria-label="Permalink to &quot;Rol: Prevencionista&quot;">​</a></h1><p>El <strong>prevencionista de riesgos</strong> es el rol técnico responsable de la gestión preventiva. Es quien opera el día a día del cumplimiento del DS 44 en la obra.</p><h2 id="responsabilidades" tabindex="-1">Responsabilidades <a class="header-anchor" href="#responsabilidades" aria-label="Permalink to &quot;Responsabilidades&quot;">​</a></h2><ul><li>Elaborar y mantener las matrices de riesgo (MIPER / MIPPER).</li><li>Crear y asignar documentos de seguridad.</li><li>Programar y registrar capacitaciones y charlas.</li><li><strong>Armar la planificación mensual de actividades</strong>: el esqueleto de charlas, ART e inspecciones por tipo, periodicidad y responsable, que los supervisores completan día a día.</li><li>Investigar incidentes y accidentes.</li><li>Hacer seguimiento del cumplimiento documental por fase.</li></ul><h2 id="permisos" tabindex="-1">Permisos <a class="header-anchor" href="#permisos" aria-label="Permalink to &quot;Permisos&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Módulo</th><th>Acceso</th></tr></thead><tbody><tr><td>Dashboard</td><td>✓ Cumplimiento, incidentes, actividades</td></tr><tr><td>Obras</td><td>👁 Solo lectura</td></tr><tr><td>Documentos</td><td>✓ Crear, asignar, gestionar</td></tr><tr><td>Firmas</td><td>✓ Completo</td></tr><tr><td>Incidentes</td><td>✓ Crear, investigar, cerrar</td></tr><tr><td>Actividades</td><td>✓ Programar, planificar el mes, registrar</td></tr><tr><td>Encuestas</td><td>✓ Crear, distribuir, analizar</td></tr><tr><td>Asistente IA</td><td>✓ Generar matrices de riesgo</td></tr><tr><td>Personas</td><td>👁 Solo lectura</td></tr><tr><td>Bandeja de Entrada</td><td>✓ Completo</td></tr><tr><td>Tenants</td><td>✗ Sin acceso</td></tr></tbody></table><h2 id="tareas-clave-en-la-plataforma" tabindex="-1">Tareas clave en la plataforma <a class="header-anchor" href="#tareas-clave-en-la-plataforma" aria-label="Permalink to &quot;Tareas clave en la plataforma&quot;">​</a></h2><ul><li><strong>Planificación mensual de actividades</strong>: con <a href="/manual/modulos/actividades.html#planificar-el-mes-completo">Planificar mes</a> genera el esqueleto del mes (charla diaria, inspecciones semanales, etc.) diferenciado por tipo de trabajo y asignado a los supervisores que corresponda. Los fines de semana se excluyen automáticamente.</li><li><strong>MIPPER asistida por IA</strong>: usa el <a href="/manual/modulos/asistente-ia.html">Asistente IA</a> para generar matrices por cargo, que revisa y firma.</li><li><strong>Asignación de documentos diarios</strong>: asigna documentos a personas, generando notificaciones automáticas en su bandeja.</li><li><strong>Destino de alertas de incidentes</strong>: recibe notificación automática cuando se reporta un incidente.</li></ul><p>Es el principal receptor de las notificaciones automáticas del sistema. Ver <a href="/manual/modulos/incidentes.html">Incidentes</a> y <a href="/manual/modulos/documentos.html">Documentos</a>.</p>',9)])])}const h=a(s,[["render",o]]);export{u as __pageData,h as default};
